// Chapter 7, batch 1 (the camp and the arc finales) cutscene stills, drawn with PixelLab, one per storyboard shot (storyboard/ch7, boards 01 and 02).
// Each cutscene is one sheet, assets/img/cut/<cutscene>.webp, its 16:9 shots stacked top to bottom. A shot plays
// under the first line holding its cue (js/vn.js, addShots). Generated by the cutscene pipeline
// (/mnt/project-files/cutscenes/pixellab/); change the spec there and re-export rather than editing this file.
(function () {
  const CUTS = [
    ['c7-arrive', ["The Free Cloud's camp, at the foot of the tower, the night before", "Pip is at the post office desk. Bru has a board out"]],
    ['c7-temp', ["For once Kai is up first", "You're not him.", "And you're not her", "They expire?"]],
    ['c7-redrive', ["Mira is sorting the last of the letters", "The Crown had a box for letters", "That's a dead-letter queue, love", "Even mine?"]],
    ['c7-key', ["Seo-yeon sits down in front of Mira with the ribbon", "Mira reties it, narrating every knot", "With an AWS managed key", "And who's on yours?", "Mira makes it a thing"]],
    ['c7-idem', ["Kai has made Bram's stew again", "Kai takes the glove off", "No.", "So it's idempotent.", "Then she takes his bare hand", "You. Just you."]],
    ['c7-on', ["Seo-yeon finds Dutch writing in the back of the diary", "Lina turned a ward on", "Like CloudTrail data events", "The wards logged who changed the rooms", "He hands her the pencil.", "She taps three, one, four", "He taps it back first."]]
  ];
  // [cutscene, cues, glitch, ghosts]: glitch lists the shots (from 1) with a painted twin, assets/img/cut/<cutscene>-<n>-painted.webp;
  // ghosts maps a shot to a figure laid over it that floats: [sprite, centre x, top y, height], in % of the shot.
  CUTS.forEach(([cut, cues, glitch = [], ghosts = {}]) => {
    const ids = cues.map((c, i) => 'cut-' + cut + '-' + (i + 1));
    const ghost = g => g && { src: 'assets/img/cut/' + g[0] + '.webp', x: g[1], y: g[2], h: g[3] };
    SD.vn.addScenes(Object.fromEntries(ids.map((id, i) => [id, { sheet: 'assets/img/cut/' + cut + '.webp', frame: i, frames: ids.length, label: id,
      glitch: glitch.includes(i + 1) ? 'assets/img/cut/' + cut + '-' + (i + 1) + '-painted.webp' : undefined, ghost: ghost(ghosts[i + 1]) }])));
    SD.vn.addShots(ids.map((id, i) => [id, cues[i]]));
  });
})();
